WITH micro AS (SELECT * FROM UNNEST(['PA-1506187-94551B72659E427F961D2F62CEBA7392','PA-1506187-CEAD1A3AC3E14F5DB2FC0B93E54E7E98','MS-5006606-4693892971CF47B4B2684C3A94950BEE','BA-2921401-9177991E4861442EACDDC06DB91','BA-2929057-C5D11EE026A64399A6EF36764E8739E9']) AS id_imovel),car AS (SELECT a.id_imovel FROM `basedosdados.br_sfb_sicar.area_imovel` a JOIN micro USING(id_imovel) WHERE data_extracao>=DATE '2026-06-02' AND data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY a.id_imovel ORDER BY a.data_extracao DESC)=1),p AS (SELECT DISTINCT REPLACE(id_car,'-','') id_car_norm,id_referencia_bacen FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao=2023),mut AS (SELECT DISTINCT id_referencia_bacen,cpf,cnpj FROM `basedosdados.br_bcb_sicor.recurso_publico_mutuario` WHERE ano_emissao=2023),x AS (SELECT c.id_imovel,p.id_referencia_bacen,m.cpf,m.cnpj FROM car c LEFT JOIN p ON p.id_car_norm=REPLACE(c.id_imovel,'-','') LEFT JOIN mut m USING(id_referencia_bacen)) SELECT id_imovel,COUNT(DISTINCT id_referencia_bacen) operacoes_vinculadas,COUNT(DISTINCT IF(cpf IS NOT NULL AND cpf!='',cpf,NULL)) cpfs,COUNT(DISTINCT IF(cnpj IS NOT NULL AND cnpj!='',cnpj,NULL)) cnpjs,ARRAY_AGG(DISTINCT COALESCE(NULLIF(cpf,''),NULLIF(cnpj,'')) IGNORE NULLS LIMIT 20) documentos FROM x GROUP BY id_imovel ORDER BY id_imovel